const { accessSync, constants } = await import('node:fs');
const pdfPath = process.env.PDF_PATH;
if (!pdfPath) throw new Error('PDF_PATH env var missing');
try { accessSync(pdfPath, constants.R_OK); } catch { throw new Error('PDF file not accessible'); }
globalThis.pdfPath = pdfPath;

const { readFileSync } = await import('node:fs');
const data = readFileSync(globalThis.pdfPath);
const decoder = new TextDecoder();
const text = decoder.decode(data);
const lines = text.split(/\r?\n/);
let heading = '';
for (const line of lines) {
  const t = line.trim();
  if (t) { heading = t; break; }
}
if (!heading) throw new Error('No heading found in PDF content');
globalThis.rawHeading = heading;

if (!globalThis.rawHeading) throw new Error('Raw heading missing');
const final = globalThis.rawHeading.trim();
if (!final) throw new Error('Final heading is empty after trim');
globalThis.heading = final;
